templates.template:
.wxClanCover { height: 220px; background-size: cover; background-position: center; border-radius: @xf-borderRadiusLarge; margin-bottom: @xf-paddingMedium; }
.wxClanLogo { width: 88px; height: 88px; object-fit: cover; border-radius: @xf-borderRadiusMedium; float: left; margin: 0 @xf-paddingMedium @xf-paddingMedium 0; }
.wxClanTag, .wxClanManagerBanner { color: #fff !important; margin-top: 3px; }

.wxClanProfileMemberships { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.wxClanProfileMembership { display: inline-flex; align-items: center; gap: 5px; padding: 4px 8px; border: 1px solid @xf-borderColor; border-radius: @xf-borderRadiusMedium; background: @xf-contentBg; text-decoration: none; }
.wxClanProfileMembership-tag { font-weight: 700; }
